# SweePurge Windows Edition - Universal Storage & Cache Purger
# Developed by A M Pabel, Team Captain at FramEmpire
# 1. Register AppUserModelID FIRST before ANY WPF/XAML initialization
$appIdCode = @"
using System;
using System.Runtime.InteropServices;

public class TaskbarIdentity {
    [DllImport("shell32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
    public static extern int SetCurrentProcessExplicitAppUserModelID(string AppID);

    [DllImport("user32.dll", SetLastError = true)]
    public static extern IntPtr SendMessage(IntPtr hWnd, uint Msg, IntPtr wParam, IntPtr lParam);
}
"@
Add-Type -TypeDefinition $appIdCode -ErrorAction SilentlyContinue
try {
    [TaskbarIdentity]::SetCurrentProcessExplicitAppUserModelID("FramEmpire.SweePurge.App.1.0") | Out-Null
} catch {}

Add-Type -AssemblyName PresentationFramework, PresentationCore, WindowsBase, System.Windows.Forms, System.Drawing

$isAdmin = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)

[xml]$xaml = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="SweePurge" Height="480" Width="480"
        WindowStartupLocation="CenterScreen" WindowStyle="None"
        AllowsTransparency="True" Background="Transparent"
        ResizeMode="CanMinimize" Topmost="False" ShowInTaskbar="True">
    <Border CornerRadius="16" Background="#18181C" BorderBrush="#2A2A32" BorderThickness="1">
        <Grid Margin="20,12,20,16">
            <Grid.RowDefinitions>
                <RowDefinition Height="28"/>
                <RowDefinition Height="Auto"/>
                <RowDefinition Height="*"/>
                <RowDefinition Height="36"/>
            </Grid.RowDefinitions>

            <!-- Window Header / Controls -->
            <Grid Grid.Row="0">
                <StackPanel Orientation="Horizontal" HorizontalAlignment="Right" VerticalAlignment="Center">
                    <Button Name="btnMinimize" Width="30" Height="24" Cursor="Hand" Margin="0,0,4,0">
                        <Button.Template>
                            <ControlTemplate TargetType="Button">
                                <Border Name="border" CornerRadius="5" Background="Transparent">
                                    <TextBlock Text="&#x2212;" FontSize="14" FontWeight="SemiBold" Foreground="#888892" HorizontalAlignment="Center" VerticalAlignment="Center" Margin="0,-2,0,0"/>
                                </Border>
                                <ControlTemplate.Triggers>
                                    <Trigger Property="IsMouseOver" Value="True">
                                        <Setter TargetName="border" Property="Background" Value="#2D2D36"/>
                                        <Setter Property="Foreground" Value="#FFFFFF"/>
                                    </Trigger>
                                </ControlTemplate.Triggers>
                            </ControlTemplate>
                        </Button.Template>
                    </Button>
                    <Button Name="btnClose" Width="30" Height="24" Cursor="Hand">
                        <Button.Template>
                            <ControlTemplate TargetType="Button">
                                <Border Name="border" CornerRadius="5" Background="Transparent">
                                    <TextBlock Text="&#x2715;" FontSize="11" FontWeight="Bold" Foreground="#888892" HorizontalAlignment="Center" VerticalAlignment="Center"/>
                                </Border>
                                <ControlTemplate.Triggers>
                                    <Trigger Property="IsMouseOver" Value="True">
                                        <Setter TargetName="border" Property="Background" Value="#E81123"/>
                                        <Setter Property="Foreground" Value="#FFFFFF"/>
                                    </Trigger>
                                </ControlTemplate.Triggers>
                            </ControlTemplate>
                        </Button.Template>
                    </Button>
                </StackPanel>
            </Grid>

            <!-- Main App Header -->
            <StackPanel Grid.Row="1" HorizontalAlignment="Center" Margin="0,4,0,14">
                <Image Name="imgAppIcon" Width="64" Height="64" HorizontalAlignment="Center" Margin="0,0,0,8" RenderOptions.BitmapScalingMode="HighQuality"/>
                <TextBlock Text="SweePurge" FontSize="20" FontWeight="Bold" Foreground="#FFFFFF" HorizontalAlignment="Center"/>
                <TextBlock Name="txtSubtitle" Text="Universal Windows Storage &amp; Cache Purger" FontSize="12" Foreground="#8E8E98" HorizontalAlignment="Center" Margin="0,3,0,0"/>
            </StackPanel>

            <!-- Main Content Area -->
            <Grid Grid.Row="2">
                <!-- VIEW 1: Ready View -->
                <StackPanel Name="panelInitial" VerticalAlignment="Center">
                    <Border CornerRadius="8" Background="#222228" Padding="14,12" Margin="0,0,0,12">
                        <StackPanel>
                            <TextBlock Text="&#x2022; 400+ Apps Caches, Adobe Media Scratch &amp; Dev Artifacts" FontSize="11.5" Foreground="#E0E0E6" Margin="0,0,0,6"/>
                            <TextBlock Text="&#x2022; Windows System Temp, Prefetch, WER &amp; Update Caches" FontSize="11.5" Foreground="#E0E0E6" Margin="0,0,0,6"/>
                            <TextBlock Text="&#x2022; Saved Application States, Crash Dumps &amp; Recycle Bin" FontSize="11.5" Foreground="#E0E0E6"/>
                        </StackPanel>
                    </Border>

                    <TextBlock Text="100% Safe: Personal files, active projects &amp; licenses untouched" FontSize="10.5" Foreground="#8E8E98" HorizontalAlignment="Center" Margin="0,0,0,16"/>

                    <!-- Deep Cleaning Mode Button -->
                    <Button Name="btnDeepClean" Height="32" Width="230" HorizontalAlignment="Center" Margin="0,0,0,12" Cursor="Hand">
                        <Button.Template>
                            <ControlTemplate TargetType="Button">
                                <Border Name="border" CornerRadius="6" Background="#282830" BorderBrush="#383844" BorderThickness="1">
                                    <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                                </Border>
                                <ControlTemplate.Triggers>
                                    <Trigger Property="IsMouseOver" Value="True">
                                        <Setter TargetName="border" Property="Background" Value="#32323D"/>
                                    </Trigger>
                                </ControlTemplate.Triggers>
                            </ControlTemplate>
                        </Button.Template>
                        <TextBlock Name="txtDeepCleanBtn" Text="Deep Cleaning Mode" FontSize="11.5" Foreground="#AEAEBA"/>
                    </Button>

                    <!-- Action Buttons -->
                    <Grid Width="340" HorizontalAlignment="Center">
                        <Grid.ColumnDefinitions>
                            <ColumnDefinition Width="*"/>
                            <ColumnDefinition Width="14"/>
                            <ColumnDefinition Width="*"/>
                        </Grid.ColumnDefinitions>

                        <Button Name="btnCancel" Grid.Column="0" Content="Cancel" Height="34" Cursor="Hand">
                            <Button.Template>
                                <ControlTemplate TargetType="Button">
                                    <Border Name="border" CornerRadius="6" Background="#282830" BorderBrush="#383844" BorderThickness="1">
                                        <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                                    </Border>
                                    <ControlTemplate.Triggers>
                                        <Trigger Property="IsMouseOver" Value="True">
                                            <Setter TargetName="border" Property="Background" Value="#32323D"/>
                                        </Trigger>
                                    </ControlTemplate.Triggers>
                                </ControlTemplate>
                            </Button.Template>
                            <Button.Foreground>
                                <SolidColorBrush Color="#D0D0D8"/>
                            </Button.Foreground>
                        </Button>

                        <Button Name="btnClean" Grid.Column="2" Content="Clean All Caches Now" Height="34" Cursor="Hand" FontWeight="Medium">
                            <Button.Template>
                                <ControlTemplate TargetType="Button">
                                    <Border Name="border" CornerRadius="6" Background="#0078D4">
                                        <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                                    </Border>
                                    <ControlTemplate.Triggers>
                                        <Trigger Property="IsMouseOver" Value="True">
                                            <Setter TargetName="border" Property="Background" Value="#1084D9"/>
                                        </Trigger>
                                    </ControlTemplate.Triggers>
                                </ControlTemplate>
                            </Button.Template>
                            <Button.Foreground>
                                <SolidColorBrush Color="#FFFFFF"/>
                            </Button.Foreground>
                        </Button>
                    </Grid>
                </StackPanel>

                <!-- VIEW 2: In-Progress View -->
                <StackPanel Name="panelProgress" VerticalAlignment="Center" Visibility="Collapsed">
                    <ProgressBar Name="progBar" Height="4" Width="280" IsIndeterminate="True" Background="#25252E" Foreground="#0078D4" BorderThickness="0" HorizontalAlignment="Center" Margin="0,0,0,18"/>
                    <TextBlock Name="txtStage" Text="Scanning system &amp; application caches..." FontSize="13" FontWeight="Medium" Foreground="#FFFFFF" HorizontalAlignment="Center" Margin="0,0,0,8"/>
                    <TextBlock Name="txtPath" Text="Initializing cleaner..." FontSize="10.5" Foreground="#70707C" HorizontalAlignment="Center" TextTrimming="CharacterEllipsis" MaxWidth="400"/>
                </StackPanel>

                <!-- VIEW 3: Completion View -->
                <StackPanel Name="panelComplete" VerticalAlignment="Center" Visibility="Collapsed">
                    <Border CornerRadius="8" Background="#222228" Padding="18,16" Margin="10,0,10,18">
                        <StackPanel HorizontalAlignment="Center">
                            <TextBlock Text="SweePurge has successfully cleaned your PC." FontSize="12.5" Foreground="#D0D0DC" HorizontalAlignment="Center" Margin="0,0,0,10"/>
                            <TextBlock Name="txtReclaimed" Text="&#x2022; Storage Reclaimed: 0 GB" FontSize="12" Foreground="#FFFFFF" HorizontalAlignment="Center" Margin="0,0,0,4"/>
                            <TextBlock Name="txtFreeTotal" Text="&#x2022; Total Available Disk Space: 0 GB" FontSize="12" Foreground="#A0A0AC" HorizontalAlignment="Center"/>
                        </StackPanel>
                    </Border>

                    <Button Name="btnDone" Content="Done" Width="140" Height="32" HorizontalAlignment="Center" Cursor="Hand">
                        <Button.Template>
                            <ControlTemplate TargetType="Button">
                                <Border Name="border" CornerRadius="6" Background="#282830" BorderBrush="#383844" BorderThickness="1">
                                    <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                                </Border>
                                <ControlTemplate.Triggers>
                                    <Trigger Property="IsMouseOver" Value="True">
                                        <Setter TargetName="border" Property="Background" Value="#32323D"/>
                                    </Trigger>
                                </ControlTemplate.Triggers>
                            </ControlTemplate>
                        </Button.Template>
                        <Button.Foreground>
                            <SolidColorBrush Color="#FFFFFF"/>
                        </Button.Foreground>
                    </Button>
                </StackPanel>
            </Grid>

            <!-- Footer: Developer Credit -->
            <StackPanel Grid.Row="3" HorizontalAlignment="Center" VerticalAlignment="Bottom">
                <TextBlock Text="Developed by" FontSize="8.5" Foreground="#555560" HorizontalAlignment="Center"/>
                <TextBlock Text="A M Pabel, Team Captain at FramEmpire" FontSize="9.5" Foreground="#666675" HorizontalAlignment="Center" Margin="0,1,0,0"/>
            </StackPanel>
        </Grid>
    </Border>
</Window>
"@

$reader = (New-Object System.Xml.XmlNodeReader $xaml)
$window = [System.Windows.Markup.XamlReader]::Load($reader)

# Enable dragging by clicking anywhere on window background

# Setup SweePurge Taskbar and Window Icon
$iconPath = Join-Path $env:TEMP "sweepurge_app.ico"
if (-not (Test-Path -LiteralPath $iconPath)) {
    $embeddedIcoB64 = ""
    try {
        [System.IO.File]::WriteAllBytes($iconPath, [System.Convert]::FromBase64String($embeddedIcoB64))
    } catch {}
}

$window.ShowInTaskbar = $true
if (Test-Path -LiteralPath $iconPath) {
    try {
        $window.Icon = [System.Windows.Media.Imaging.BitmapFrame]::Create([Uri]$iconPath)
    } catch {}
}

$window.Add_SourceInitialized({
    try {
        if (Test-Path -LiteralPath $iconPath) {
            $icoObj = New-Object System.Drawing.Icon($iconPath)
            $hwnd = (New-Object System.Windows.Interop.WindowInteropHelper($window)).Handle
            [TaskbarIdentity]::SendMessage($hwnd, 0x0080, [IntPtr]1, $icoObj.Handle) | Out-Null # WM_SETICON ICON_BIG
            [TaskbarIdentity]::SendMessage($hwnd, 0x0080, [IntPtr]0, $icoObj.Handle) | Out-Null # WM_SETICON ICON_SMALL
        }
    } catch {}
})

$window.Add_MouseLeftButtonDown({
    if ($_.ButtonState -eq [System.Windows.Input.MouseButtonState]::Pressed) {
        $window.DragMove()
    }
})

# Load base64 app icon
$iconBase64 = ""
try {
    $bytes = [System.Convert]::FromBase64String($iconBase64)
    $memStream = New-Object System.IO.MemoryStream($bytes, 0, $bytes.Length)
    $bitmap = New-Object System.Windows.Media.Imaging.BitmapImage
    $bitmap.BeginInit()
    $bitmap.StreamSource = $memStream
    $bitmap.EndInit()
    $imgIcon = $window.FindName("imgAppIcon")
    $imgIcon.Source = $bitmap
} catch {}

# Find controls
$btnMinimize = $window.FindName("btnMinimize")
$btnClose = $window.FindName("btnClose")
$btnCancel = $window.FindName("btnCancel")
$btnClean = $window.FindName("btnClean")
$btnDeepClean = $window.FindName("btnDeepClean")
$txtDeepCleanBtn = $window.FindName("txtDeepCleanBtn")
$btnDone = $window.FindName("btnDone")

$panelInitial = $window.FindName("panelInitial")
$panelProgress = $window.FindName("panelProgress")
$panelComplete = $window.FindName("panelComplete")

$txtSubtitle = $window.FindName("txtSubtitle")
$txtStage = $window.FindName("txtStage")
$txtPath = $window.FindName("txtPath")
$txtReclaimed = $window.FindName("txtReclaimed")
$txtFreeTotal = $window.FindName("txtFreeTotal")

if ($isAdmin) {
    $txtDeepCleanBtn.Text = "Deep Cleaning: Active"
    $txtDeepCleanBtn.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#4CC2FF")
}

$btnMinimize.Add_Click({ $window.WindowState = [System.Windows.WindowState]::Minimized })
$btnClose.Add_Click({ $window.Close(); [System.Environment]::Exit(0) })
$btnCancel.Add_Click({ $window.Close(); [System.Environment]::Exit(0) })
$btnDone.Add_Click({ $window.Close(); [System.Environment]::Exit(0) })

# Deep Cleaning Clicked
$btnDeepClean.Add_Click({
    if (-not $isAdmin) {
        $res = [System.Windows.MessageBox]::Show(
            "Deep Cleaning allows SweePurge to unlock 20-50+ GB of protected Windows storage:`n" +
            ([char]0x2022) + " Windows Update Download Cache (SoftwareDistribution)`n" +
            ([char]0x2022) + " Windows Prefetch Files`n" +
            ([char]0x2022) + " System Temp Directory`n`n" +
            "To enable this, Administrator privileges are required.`n`n" +
            "Would you like to restart SweePurge as Administrator?",
            "Deep Cleaning Mode",
            [System.Windows.MessageBoxButton]::YesNo,
            [System.Windows.MessageBoxImage]::Information
        )
        if ($res -eq [System.Windows.MessageBoxResult]::Yes) {
            try {
                $exePath = [System.Diagnostics.Process]::GetCurrentProcess().MainModule.FileName
                if ($exePath -like "*powershell*") {
                    Start-Process powershell.exe -ArgumentList "-NoProfile -ExecutionPolicy Bypass -File `"$PSCommandPath`"" -Verb RunAs
                } else {
                    Start-Process $exePath -Verb RunAs
                }
                $window.Close()
                [System.Environment]::Exit(0)
            } catch {}
        }
    }
})

# Helper: Format Bytes
function Format-Bytes([Int64]$bytes) {
    if ($bytes -ge 1GB) { return "{0:N2} GB" -f ($bytes / 1GB) }
    if ($bytes -ge 1MB) { return "{0:N1} MB" -f ($bytes / 1MB) }
    if ($bytes -ge 1KB) { return "{0:N0} KB" -f ($bytes / 1KB) }
    return "$bytes B"
}

# Helper: Get Free Disk Space
function Get-DriveFreeSpace() {
    try {
        $drive = Get-PSDrive -Name C -ErrorAction SilentlyContinue
        if ($drive) { return [Int64]$drive.Free }
    } catch {}
    return 0
}

function Invoke-UIUpdate {
    try { Invoke-UIUpdate } catch {}
    try {
        $frame = New-Object System.Windows.Threading.DispatcherFrame
        [System.Windows.Threading.Dispatcher]::CurrentDispatcher.BeginInvoke(
            [System.Windows.Threading.DispatcherPriority]::Background,
            [Action]{ $frame.Continue = $false }
        ) | Out-Null
        [System.Windows.Threading.Dispatcher]::PushFrame($frame)
    } catch {}
}

# Throttled Path Reporter
$global:lastUpdate = [DateTime]::MinValue
function Update-ProgressUI([string]$stage, [string]$path) {
    $now = [DateTime]::Now
    if (($now - $global:lastUpdate).TotalMilliseconds -ge 40 -or $path -eq "") {
        $global:lastUpdate = $now
        $txtStage.Text = $stage
        if ($path -ne "") {
            $txtPath.Text = $path
        }
        Invoke-UIUpdate
    }
}

# Directory Cleaning Helper
function Clean-DirContents([string]$targetDir, [string]$stageName) {
    if (-not (Test-Path -LiteralPath $targetDir)) { return }
    try {
        $items = Get-ChildItem -LiteralPath $targetDir -Force -ErrorAction SilentlyContinue
        foreach ($item in $items) {
            Update-ProgressUI $stageName $item.FullName
            try {
                Remove-Item -LiteralPath $item.FullName -Recurse -Force -ErrorAction SilentlyContinue
            } catch {}
        }
    } catch {}
}

# Cleaning Execution
$btnClean.Add_Click({
    $panelInitial.Visibility = [System.Windows.Visibility]::Collapsed
    $panelProgress.Visibility = [System.Windows.Visibility]::Visible
    $txtSubtitle.Text = "Optimizing Windows Storage..."
    Invoke-UIUpdate

    $freeBefore = Get-DriveFreeSpace

    # 1. TIER 1: USER & SYSTEM TEMP
    Update-ProgressUI "Purging Windows Temporary Files..." ""
    Clean-DirContents $env:TEMP "Purging Windows Temporary Files..."
    if ($isAdmin) {
        Clean-DirContents "C:\Windows\Temp" "Purging System Temp Directory..."
        Clean-DirContents "C:\Windows\Prefetch" "Cleaning Windows Prefetch Files..."
        Clean-DirContents "C:\Windows\SoftwareDistribution\Download" "Purging Windows Update Cache..."
    }

    # 2. TIER 2: 400+ APPS & BROWSERS
    Update-ProgressUI "Purging 400+ Apps & Browser Caches..." ""
    $browserPaths = @(
        "$env:LOCALAPPDATA\Google\Chrome\User Data\Default\Cache",
        "$env:LOCALAPPDATA\Google\Chrome\User Data\Default\Code Cache",
        "$env:LOCALAPPDATA\Google\Chrome\User Data\Default\GPUCache",
        "$env:LOCALAPPDATA\Google\Chrome\User Data\ShaderCache",
        "$env:LOCALAPPDATA\Microsoft\Edge\User Data\Default\Cache",
        "$env:LOCALAPPDATA\Microsoft\Edge\User Data\Default\Code Cache",
        "$env:LOCALAPPDATA\Microsoft\Edge\User Data\Default\GPUCache",
        "$env:LOCALAPPDATA\BraveSoftware\Brave-Browser\User Data\Default\Cache",
        "$env:LOCALAPPDATA\Opera Software\Opera Stable\Cache",
        "$env:APPDATA\discord\Cache",
        "$env:APPDATA\discord\Code Cache",
        "$env:APPDATA\discord\GPUCache",
        "$env:APPDATA\Slack\Cache",
        "$env:APPDATA\Slack\Code Cache",
        "$env:APPDATA\Telegram Desktop\tdata\user_data",
        "$env:LOCALAPPDATA\Spotify\Storage",
        "$env:LOCALAPPDATA\Spotify\Data"
    )
    foreach ($bp in $browserPaths) {
        Clean-DirContents $bp "Purging Browser & App Caches..."
    }

    # Electron / AppData Cache Sweep
    $localAppSubdirs = Get-ChildItem -LiteralPath $env:LOCALAPPDATA -Directory -ErrorAction SilentlyContinue
    $cacheFolderNames = @("Cache", "Code Cache", "GPUCache", "DawnCache", "ShaderCache", "CachedData")
    foreach ($dir in $localAppSubdirs) {
        foreach ($c in $cacheFolderNames) {
            $target = Join-Path $dir.FullName $c
            if (Test-Path -LiteralPath $target) {
                Clean-DirContents $target "Cleaning Electron App Caches..."
            }
        }
    }

    # 3. TIER 3: PRO VIDEO, 3D & CREATIVE SUITES
    Update-ProgressUI "Purging Adobe Media Caches & Scratch Disks..." ""
    $adobePaths = @(
        "$env:APPDATA\Adobe\Common\Media Cache Files",
        "$env:APPDATA\Adobe\Common\Media Cache",
        "$env:APPDATA\Adobe\Common\Peak Files",
        "$env:APPDATA\Adobe\CameraRaw\Cache",
        "$env:LOCALAPPDATA\Adobe\CameraRaw\Cache",
        "$env:APPDATA\Blackmagic Design\DaVinci Resolve\Support\CacheClip",
        "$env:APPDATA\Blackmagic Design\DaVinci Resolve\Support\.gallery",
        "$env:APPDATA\Blackmagic Design\DaVinci Resolve\Support\ProxyMedia",
        "$env:LOCALAPPDATA\UnrealEngine\Common\DerivedDataCache",
        "$env:LOCALAPPDATA\EpicGamesLauncher\Saved\Logs",
        "$env:LOCALAPPDATA\Unity\cache",
        "$env:LOCALAPPDATA\UnityEditor\Cache"
    )
    foreach ($ap in $adobePaths) {
        Clean-DirContents $ap "Purging Creative Media Caches..."
    }

    # 4. TIER 4: DEVELOPER & BUILD ARTIFACTS
    Update-ProgressUI "Cleaning Developer Toolchains & Build Artifacts..." ""
    $devPaths = @(
        "$env:APPDATA\Code\Cache",
        "$env:APPDATA\Code\CachedData",
        "$env:APPDATA\Cursor\Cache",
        "$env:APPDATA\Cursor\CachedData",
        "$env:USERPROFILE\.gradle\caches",
        "$env:USERPROFILE\.m2\repository\.cache",
        "$env:USERPROFILE\.cargo\registry\cache",
        "$env:USERPROFILE\.rustup\downloads",
        "$env:LOCALAPPDATA\npm-cache",
        "$env:LOCALAPPDATA\pnpm\store",
        "$env:LOCALAPPDATA\Yarn\Cache",
        "$env:LOCALAPPDATA\pip\cache",
        "$env:LOCALAPPDATA\NuGet\v3-cache"
    )
    foreach ($dp in $devPaths) {
        Clean-DirContents $dp "Cleaning Developer Build Artifacts..."
    }

    # 5. TIER 5: CRASH DUMPS, STALE DOWNLOADS & RECYCLE BIN
    Update-ProgressUI "Reclaiming Crash Dumps & Stale Downloads..." ""
    Clean-DirContents "$env:LOCALAPPDATA\CrashDumps" "Cleaning Crash Dumps..."
    Clean-DirContents "C:\ProgramData\Microsoft\Windows\WER" "Cleaning Windows Error Reports..."

    # Incomplete Downloads
    $dlPath = "$env:USERPROFILE\Downloads"
    if (Test-Path -LiteralPath $dlPath) {
        Get-ChildItem -LiteralPath $dlPath -File -ErrorAction SilentlyContinue | Where-Object {
            $_.Extension -in @(".crdownload", ".part", ".download")
        } | ForEach-Object {
            Update-ProgressUI "Removing Partial Downloads..." $_.FullName
            Remove-Item -LiteralPath $_.FullName -Force -ErrorAction SilentlyContinue
        }
    }

    # Empty Recycle Bin
    Update-ProgressUI "Emptying Windows Recycle Bin..." ""
    try {
        Clear-RecycleBin -Force -ErrorAction SilentlyContinue
    } catch {}

    $freeAfter = Get-DriveFreeSpace
    $reclaimedBytes = [Math]::Max(0, $freeAfter - $freeBefore)

    $panelProgress.Visibility = [System.Windows.Visibility]::Collapsed
    $panelComplete.Visibility = [System.Windows.Visibility]::Visible
    $txtSubtitle.Text = "Optimization Complete"

    $txtReclaimed.Text = ([char]0x2022) + " Storage Reclaimed: " + (Format-Bytes $reclaimedBytes)
    $txtFreeTotal.Text = ([char]0x2022) + " Total Available Disk Space: " + (Format-Bytes $freeAfter)
})

$window.ShowDialog() | Out-Null
